    s += '<ellipse cx="212" cy="226" rx="40" ry="12" fill="#9AA4B1"/><ellipse cx="206" cy="220" rx="34" ry="12" fill="#B4BCC7"/>';
    s += person(214, 222, { k: 0.72, sit: true, top: C.orange, mouth: 'sad', tears: true })
