      + person(290, 214, { k: 0.86, top: C.aqua, hair: 'long', mouth: 'o', arm: 'point', armSide: -1, armAngle: -120 });
    // the book between them
    s += '<path d="M245 150c-14-6-30-6-42-2v34c12-4 28-4 42 2z" fill="#fff" stroke="#54A0FF" stroke-width="3"/><path d="M245 150c14-6 30-6 42-2v34c-12-4-28-4-42 2z" fill="#fff" stroke="#54A0FF" stroke-width="3"/>'
