      + '<path d="M0 0V-24" stroke="#303749" stroke-width="5" stroke-linecap="round"/><path d="M0 -32A32 32 0 0 1 32 0H0z" fill="#FECA57" opacity=".6"/><circle r="5" fill="#303749"/></g>'
      + sparkle(350, 40, 0.8) + sparkle(460, 150, 0.6, C.pink);
