const stageIcon = (id) => (STAGE_ICON[id] ? STAGE_ICON[id]() : '');

// a face for a speaker in the read-aloud lines: a kind of face (girl in a headscarf, cheeky boy,
// a man in a cap …) from the lesson's speakers list, otherwise one colour per speaker in turn
const FACE_TOPS = ['#8E5BC6', '#2E86DE', '#FF9F43', '#16A085', '#FF6B6B'];
const FACE_KIND = {
  girl_scarf: { hair: 'scarf', scarf: C.pink, top: '#8E5BC6' }, girl: { hair: 'long', top: C.pink }, boy: { hair: 'short', top: C.skyD },
  boy_cheeky: { hair: 'short', top: C.orange, mouth: 'grin' }, man_cap: { hair: 'cap', cap: C.green, top: '#6C7A89', beard: '#3B2F2F' },
  man_moustache: { hair: 'short', top: '#4A69BD', moustache: HAIR }, elder: { hair: 'grey', beard: '#E3E6EC', top: '#6C7A89' },
  woman: { hair: 'scarf', scarf: C.violet, top: '#16A085' },
};
function face(i, kind) {
  const o = FACE_KIND[kind] || { hair: 'short', top: FACE_TOPS[i % FACE_TOPS.length] };
  const bg = ['#FFE3E3', '#E3F0FF', '#FFF1D6', '#DDF7EC', '#EFE3FF'][i % 5];
  return `<svg class="qface" viewBox="-36 -142 72 72" aria-hidden="true"><circle cx="0" cy="-106" r="36" fill="${bg}"/>${person(0, 0, { ...o, k: 1 })}</svg>`;
}

const DRAW = { clock, clock_pair: clockPair, tiles, blender, blender_list: blenderList, blend_steps: blendSteps, scene, predict, dictionary, poster };
// the visual types drawn as HTML by primary.js rather than as SVG here
const HTML_VISUALS = ['story_map', 'tracker'];
function draw(spec) {
  if (!spec || !spec.type) return '';
  const f = DRAW[spec.type];
  if (!f) throw new Error(`no drawing for visual type "${spec.type}"`);
  return f(spec);
}

module.exports = { draw, DRAW, HTML_VISUALS, heroBadge, ICON, stageIcon, face, parseTime, C };
